interface DeliverySink { onFailure(reason: string): void }
export class CapacityRelay {
 connect(engine: Engine, target: DeliverySink): void {
  engine.observe({
   onEvent00: (reason: string) => { target.onFailure(reason) },
   onEvent01: (reason: string) => { target.onFailure(reason) },
   onEvent02: (reason: string) => { target.onFailure(reason) },
