   onEvent07: (reason: string) => { target.onFailure(reason) },
   onEvent08: (reason: string) => { target.onFailure(reason) },
   onEvent09: (reason: string) => { target.onFailure(reason) },
   onEvent10: (reason: string) => { target.onFailure(reason) },
   onEvent11: (reason: string) => { target.onFailure(reason) },
   onEvent12: (reason: string) => { target.onFailure(reason) },
   onEvent13: (reason: string) => { target.onFailure(reason) },
   onEvent14: (reason: string) => { target.onFailure(reason) },
   onEvent15: (reason: string) => { target.onFailure(reason) }
  })
 }
}
